query:
SELECT vv.id, vv.vehicleId, vv.status, v.brand, v.model, v.status as vehicleStatus
FROM vehicle_verifications vv
JOIN vehicles v ON v.id = vv.vehicleId;

UPDATE vehicles SET status = 'pending_approval' WHERE crlvUrl IS NOT NULL AND status = 'active';

